{{-- Filtres : $filters (App\Support\Filters), $show = liste des filtres affichés --}}
@php $o = $filters->options(); $show = $show ?? ['year', 'faculty', 'promotion', 'currency']; @endphp
<form class="filters" method="get" data-cascade>
    @if(in_array('q', $show))<div style="flex-basis:220px"><label class="form-label" for="f-q">Recherche</label><input id="f-q" type="search" name="q" class="form-control" value="{{ $filters->get('q') }}" placeholder="{{ $qPlaceholder ?? 'Matricule, nom, référence…' }}"></div>@endif
    @if(in_array('year', $show))<div><label class="form-label" for="f-year">Année académique</label><select id="f-year" name="year" class="form-select">@foreach($o['years'] as $y)<option value="{{ $y->id }}" @selected($filters->get('year') == $y->id)>{{ $y->code }}{{ $y->status === 'closed' ? ' (clôturée)' : '' }}</option>@endforeach</select></div>@endif
    @if(in_array('faculty', $show))<div><label class="form-label" for="f-fac">Faculté</label><select id="f-fac" name="faculty" class="form-select" data-faculty><option value="">{{ $filters->facultyScope === null ? 'Toutes' : 'Toutes (mon périmètre)' }}</option>@foreach($o['faculties'] as $fa)<option value="{{ $fa->id }}" @selected($filters->get('faculty') == $fa->id)>{{ $fa->code }} — {{ $fa->name }}</option>@endforeach</select></div>@endif
    @if(in_array('program', $show))<div><label class="form-label" for="f-prog">Filière</label><select id="f-prog" name="program" class="form-select"><option value="">Toutes</option>@foreach($o['programs'] as $p)<option value="{{ $p->id }}" data-fac="{{ $p->department->faculty_id }}" @selected($filters->get('program') == $p->id)>{{ $p->name }}</option>@endforeach</select></div>@endif
    @if(in_array('promotion', $show))<div><label class="form-label" for="f-promo">Promotion</label><select id="f-promo" name="promotion" class="form-select" data-promotion><option value="">Toutes</option>@foreach($o['promotions'] as $p)<option value="{{ $p->id }}" data-fac="{{ $p->program->department->faculty_id }}" @selected($filters->get('promotion') == $p->id)>{{ $p->code }} — {{ $p->name }}</option>@endforeach</select></div>@endif
    @if(in_array('fee', $show))<div><label class="form-label" for="f-fee">Frais</label><select id="f-fee" name="fee" class="form-select"><option value="">Tous</option>@foreach($o['fees'] as $fe)<option value="{{ $fe->id }}" @selected($filters->get('fee') == $fe->id)>{{ $fe->label }}</option>@endforeach</select></div>@endif
    @if(in_array('account', $show))<div><label class="form-label" for="f-acc">Banque / compte</label><select id="f-acc" name="account" class="form-select"><option value="">Tous</option>@foreach($o['accounts'] as $a)<option value="{{ $a->id }}" @selected($filters->get('account') == $a->id)>{{ $a->bank->code }} {{ $a->account_number }} ({{ $a->currency }})</option>@endforeach</select></div>@endif
    @if(in_array('currency', $show))<div style="flex-basis:110px"><label class="form-label" for="f-cur">Devise</label><select id="f-cur" name="currency" class="form-select"><option value="">Toutes</option>@foreach($o['currencies'] as $c)<option @selected($filters->get('currency') === $c)>{{ $c }}</option>@endforeach</select></div>@endif
    @if(in_array('period', $show))<div style="flex-basis:150px"><label class="form-label" for="f-from">Du (date bancaire)</label><input id="f-from" type="date" name="from" class="form-control" value="{{ $filters->get('from') }}"></div><div style="flex-basis:150px"><label class="form-label" for="f-to">Au</label><input id="f-to" type="date" name="to" class="form-control" value="{{ $filters->get('to') }}"></div>@endif
    @if(in_array('status', $show) && isset($statuses))<div><label class="form-label" for="f-st">Statut</label><select id="f-st" name="status" class="form-select"><option value="">Tous</option>@foreach($statuses as $k => $v)<option value="{{ $k }}" @selected($filters->get('status') === $k)>{{ $v }}</option>@endforeach</select></div>@endif
    <div class="acts"><button class="btn btn-primary"><i class="bi bi-funnel"></i> Filtrer</button></div>
</form>
